mapper.select:
SELECT id, operator_id, operator_name, module, op_type,
       op_result, result_msg, target_desc, op_ip, op_time
FROM operation_log


        AND module = #{query.module}


        AND op_type = #{query.opType}


        AND operator_name LIKE CONCAT('%', #{query.operator}, '%')


        AND op_time >= #{query.startTime}


        AND op_time <= #{query.endTime}


ORDER BY op_time DESC, id DESC
